DUALDEFS = r'''
def pc.@F@_mget(m: Maybe<&2, @BLK@>, +d: @BLK@) -> @BLK@:
  match m:
    case Some{b}:
      b
    case None{}:
      d

def pc.@F@_mdisc(m: Maybe<&2, @BLK@>) -> Type:
  match m:
    case Some{b}:
      Empty
    case None{}:
      Unit

def pc.@F@_nsome(+bl: @BLK@, h: {None{} == Some{bl} : Maybe<&2, @BLK@>}) -> Empty:
  %h : pc.@F@_mdisc(_)
  Unit{}

@DUALBITS@

@DUALL@

def pc.@F@_dual(+o: B.Octets, +bl: @BLK@, em: {@OF@(o) == Some{bl} : Maybe<&2, @BLK@>}) -> {@TO@(bl) == o : B.Octets}:
  Equal.trans(B.Octets, @TO@(bl), B.Octets.of_list(B.Octets.to_list(o)), o, pc.@F@_dualL(B.Octets.to_list(o), bl)(em), BL.octets_of_to(o))

'''

FORMATS = [
    dict(F='cm', SUF='', NAME='The 128-bit block format (inst_cm.bend)', BLK='M.CmBlock', OF='CM.CrBlk128.of_octets', TO='CM.CrBlk128.to_octets',
         N='16n', Q='15n', NB=16, ZERO='M.CmBlock{0, 0, 0, 0}', FMT='PB.pb.cm_fmt', LEN='PB.pb.cm_len', BLOCK='CM.cr.f128.block', DUAL='pc.cm_dual'),
    dict(F='lc', SUF='64', NAME="The 64-bit block format (cipher-core's LcBlock64)", BLK='L.LcBlock64', OF='L.LcBlock64.of_octets', TO='L.LcBlock64.to_octets',
         N='8n', Q='7n', NB=8, ZERO='L.LcBlock64{0, 0}', FMT='CoreL.block64_octets_round_trip', LEN='PB.pb.lc_len', DUAL='CoreL.block64_octets_dual'),
]

def u32(p):
    return "U32{" + "".join("WCon{%s_%d, " % (p, i) for i in range(32)) + "WNil{}" + "}" * 32 + "}"

def lst(names, tail='Nil{}'):
    s = tail
    for n in reversed(names):
        s = "Con{%s, %s}" % (n, s)
    return s

def gen(f):
    if 'BLOCK' not in f:
        s = TEMPLATE.replace('@DUALDEFS@', '')
        for k, v in f.items():
            s = s.replace('@%s@' % k, str(v))
        return s
    nb = f['NB']
    a = ["a%d" % i for i in range(nb)]
    full = lst(a)
    dbits = ("# a block's bytes read from %d bytes are those bytes (on their bits)\n"
             "def pc.%s_dbits(%s) -> {%s(pc.%s_mget(%s(%s), %s)) == B.Octets.of_list(%s) : B.Octets}:\n"
             "  match %s:\n    case %s:\n      {==}\n") % (
        nb, f['F'], ", ".join("%s: U32" % x for x in a), f['TO'], f['F'], f['BLOCK'], full, f['ZERO'], full,
        " ".join(a), " ".join(u32("b%d" % i) for i in range(nb)))
    # dualL: nested matches
    lines = ["# a block read from a list of bytes is written back as those bytes",
             "def pc.%s_dualL(+xs: List<&2, U32>, +bl: %s) -> {%s(xs) == Some{bl} : Maybe<&2, %s>} -> {%s(bl) == B.Octets.of_list(xs) : B.Octets}:" % (f['F'], f['BLK'], f['BLOCK'], f['BLK'], f['TO'])]
    ind = "  "
    var = "xs"
    for i in range(nb + 1):
        got = a[:i]
        lines.append(ind + "match %s:" % var)
        lines.append(ind + "  case Nil{}:")
        if i == nb:
            lines.append(ind + "    h => %%Equal.cong(Maybe<&2, %s>, %s, mm => pc.%s_mget(mm, bl), %s(%s), Some{bl}, h) : {%s(_) == B.Octets.of_list(%s) : B.Octets}" % (
                f['BLK'], f['BLK'], f['F'], f['BLOCK'], full, f['TO'], full))
            lines.append(ind + "      pc.%s_dbits(%s)" % (f['F'], ", ".join(a)))
        else:
            lines.append(ind + "    h => Empty.absurd({%s(bl) == B.Octets.of_list(%s) : B.Octets}, pc.%s_nsome(bl, h))" % (f['TO'], lst(got), f['F']))
        nxt = "x%d" % (i + 1)
        if i == nb:
            lines.append(ind + "  case Con{+a%d, +%s}:" % (i, nxt))
            lines.append(ind + "    h => Empty.absurd({%s(bl) == B.Octets.of_list(%s) : B.Octets}, pc.%s_nsome(bl, h))" % (f['TO'], lst(a + ["a%d" % i], nxt), f['F']))
        else:
            lines.append(ind + "  case Con{+a%d, +%s}:" % (i, nxt))
        ind += "    "
        var = nxt
    duall = "\n".join(lines) + "\n"
    s = TEMPLATE
    # a format whose package states its byte form both ways as a law (DUAL
    # names it) needs no lemmas of its own; inst_cm.bend's is proved here
    s = s.replace('@DUALDEFS@', DUALDEFS[:-1])
    s = s.replace('@DUALBITS@', dbits).replace('@DUALL@', duall)
    for k, v in f.items():
        s = s.replace('@%s@' % k, str(v))
    return s



def main():
    check = "--check" in sys.argv[1:]
    with open(PROOF) as f:
        text = f.read()
    begin = "# BEGIN GENERATED by gen/cts_proof.py: formats\n"
    end = "# END GENERATED: formats\n"
    i, j = text.index(begin) + len(begin), text.index(end)
    new = text[:i] + "\n".join(gen(f) for f in FORMATS) + text[j:]
    if check:
        if new != text:
            print("PROOF_cts.bend: region formats is out of date (run gen/cts_proof.py)")
            sys.exit(1)
        print("PROOF_cts.bend: up to date")
        return
    with open(PROOF, "w", newline="\n") as f:
        f.write(new)


if __name__ == "__main__":
    main()
